package dev.hryshyn.remanence.ui.collage

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Reference-vs-Kotlin differential test for the frozen V5 grammar-5 branch
 * enumeration.
 *
 * The expected geometry in
 * `src/test/resources/collage/v5_grammar5_reference.txt` is generated by
 * `tasks/T151/evidence/ref_grammar5.js`, which extracts the authoritative
 * freeze functions verbatim from
 * `remanence_capsule_engine_v5_freeze_2026-09-25/runtime/grammars.js`
 * (`recipes` :42, `bands` :37-41, `closing` :43-47, grammar-5 `basePlans`
 * :51-54) and projects floats to the Android integer canvas with `Math.floor`
 * per rect. Branches are compared by `branchId` (enumeration order is a
 * presentation detail), so this pins the ported geometry exactly.
 */
class Grammar5BranchesTest {

    private class RefBranch(
        val branchId: String,
        val noteRegion: List<Int>?,
        val musicRegion: List<Int>?,
        val cells: List<List<Int>>,
    )

    private class RefCase(
        val n: Int,
        val noteHeight: Int?,
        val music: Boolean,
        val aspects: List<Double>,
        val branches: MutableList<RefBranch> = ArrayList(),
    )

    private fun rect(value: String): List<Int>? =
        if (value == "-") null else value.split(',').map { it.toInt() }

    private fun reference(): List<RefCase> {
        val text = requireNotNull(
            javaClass.getResource("/collage/v5_grammar5_reference.txt"),
        ) { "missing grammar-5 reference fixture" }.readText()
        val cases = ArrayList<RefCase>()
        for (raw in text.lineSequence()) {
            val line = raw.trimEnd('\r')
            if (line.isBlank() || line.startsWith("#")) continue
            val parts = line.split('\t')
            when (parts.first()) {
                "CASE" -> cases += RefCase(
                    n = parts[1].toInt(),
                    noteHeight = parts[2].let { if (it == "null") null else it.toInt() },
                    music = parts[3].toBoolean(),
                    aspects = parts[4].split(',').map { it.toDouble() },
                )
                "BRANCH" -> {
                    require(cases.isNotEmpty()) { "BRANCH before CASE" }
                    cases.last().branches += RefBranch(
                        branchId = parts[1],
                        noteRegion = rect(parts[2]),
                        musicRegion = rect(parts[3]),
                        cells = parts[4].split(';').map { requireNotNull(rect(it)) },
                    )
                }
            }
        }
        return cases
    }

    @Test
    fun frozenReferenceCoversAllThreeCountsAndNotesAndMusic() {
        val ref = reference()
        assertEquals(setOf(3, 4, 5), ref.map { it.n }.toSet())
        assertTrue(ref.any { it.noteHeight != null })
        assertTrue(ref.any { it.noteHeight == null })
        assertTrue(ref.any { it.music })
        assertTrue(ref.any { !it.music })
    }

    @Test
    fun kotlinEnumerationMatchesFrozenReferenceGeometry() {
        for (case in reference()) {
            val label = "n=${case.n} aspects=${case.aspects} note=${case.noteHeight} music=${case.music}"
            val grids = Grammar5Branches.grids(case.aspects, case.noteHeight, case.music)
            assertEquals("branch count ($label)", case.branches.size, grids.size)
            val byId = grids.associateBy { it.branchId }
            for (expected in case.branches) {
                val grid = byId[expected.branchId]
                assertTrue("missing branch ${expected.branchId} ($label)", grid != null)
                val actual = requireNotNull(grid)
                assertEquals(
                    "cells ${expected.branchId} ($label)",
                    expected.cells,
                    actual.cells.map { listOf(it.x, it.y, it.width, it.height) },
                )
                assertEquals(
                    "noteRegion ${expected.branchId} ($label)",
                    expected.noteRegion,
                    actual.noteRegion?.let { listOf(it.x, it.y, it.width, it.height) },
                )
                assertEquals(
                    "musicRegion ${expected.branchId} ($label)",
                    expected.musicRegion,
                    actual.musicRegion?.let { listOf(it.x, it.y, it.width, it.height) },
                )
            }
        }
    }

    @Test
    fun branchCountsMatchTheFrozenRecipePowerWeightProduct() {
        assertEquals(12, Grammar5Branches.grids(List(3) { 1.0 }, null, false).size)
        assertEquals(12, Grammar5Branches.grids(List(4) { 1.0 }, null, false).size)
        assertEquals(18, Grammar5Branches.grids(List(5) { 1.0 }, null, false).size)
    }

    @Test
    fun legacyEqualOneBranchIsPreservedPerCount() {
        for (n in 3..5) {
            val legacy = requireNotNull(Grammar5Grid.place(n, null, false)) { "legacy place must resolve for n=$n" }
            val fromEnumeration = Grammar5Branches.grids(List(n) { 1.0 }, null, false)
                .firstOrNull { it.branchId == legacy.branchId }
            assertTrue("enumeration must contain ${legacy.branchId}", fromEnumeration != null)
            assertEquals(legacy.cells, requireNotNull(fromEnumeration).cells)
            assertEquals(legacy.noteRegion, requireNotNull(fromEnumeration).noteRegion)
            assertEquals(legacy.musicRegion, requireNotNull(fromEnumeration).musicRegion)
        }
    }

    @Test
    fun powerOneUsesSourceAspectRatiosAndPowerZeroDoesNot() {
        val aspects = listOf(1.5, 0.6667, 1.0)
        val equal = Grammar5Branches.grids(aspects, null, false).first { it.branchId.endsWith("equal-1") }
        val proportional = Grammar5Branches.grids(aspects, null, false)
            .first { it.branchId.endsWith("proportional-1") }
        // Row 0 is a single cell, so the hero width is full in both; row 1's
        // two cells split proportionally to the clamped aspect ratios.
        val equalRow1 = equal.cells.drop(1).map { it.width }
        val propRow1 = proportional.cells.drop(1).map { it.width }
        assertEquals(equalRow1[0], equalRow1[1])
        assertTrue("proportional row widths must differ for unequal aspects: $propRow1", propRow1[0] != propRow1[1])
        assertEquals(equal.cells[0], proportional.cells[0])
    }
}
